// You'll use this same dataset across all 7 phases:
//   Excel → SQL → Python → Power BI → Tableau → Portfolio

{
  "order_id": "ORD-20260118-7741",
  "customer_id": "CUS-9182",
  "store": "Berlin Mitte",
  "region": "DACH",
  "product": "Wireless Headphones X3",
  "category": "Electronics",
  "quantity": 2,
  "unit_price": 149.00,
  "discount_pct": 10,
  "channel": "online",
  "order_date": "2026-01-18T14:32:00Z"
}

// Phase 1: Clean & pivot it in Excel
// Phase 2: Query it with SQL (top products, cohorts)
// Phase 3: Reshape it with Pandas
// Phase 4: Build the Sales Performance dashboard in Power BI
// Phase 5: Build the same dashboard in Tableau
// Phase 6: Tell the story with stats + executive summary
// Phase 7: Put the live dashboards on your portfolio + resume

// Revenue (calculated field)
[Quantity] * [Unit Price] * (1 - [Discount Pct] / 100)

// YoY % (table calculation)
( SUM([Revenue])
- LOOKUP(SUM([Revenue]), -12) )
/ LOOKUP(SUM([Revenue]), -12)

// LOD — Customer lifetime revenue (regardless of filters)
{ FIXED [Customer ID] : SUM([Revenue]) }

// LOD — % of store revenue by category
SUM([Revenue]) /
{ FIXED [Store] : SUM([Revenue]) }

// Cohort label
"Cohort " + STR(YEAR({ FIXED [Customer ID] : MIN([Order Date]) }))

/* Dashboard wired to:
   ✓ KPI tiles: Revenue, YoY %, AOV
   ✓ Map: Revenue by Store (filled map)
   ✓ Bar: Top 10 products
   ✓ Line: Daily revenue with 7-day moving average
   ✓ Cohort retention heatmap (LOD-powered) */
